412	    /// The path didn't match any glob.
413	    None,
414	    /// The highest precedent glob matched indicates the path should be
415	    /// ignored.
416	    Ignore(T),
417	    /// The highest precedent glob matched indicates the path should be
418	    /// whitelisted.
419	    Whitelist(T),
420	}
